const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const square = [];
let index = 1;
let zeroRow = 0;
let zeroCol = 0;

for (let i = 0; i < n; i++) {
  square[i] = data.slice(index, index + n);
  index += n;

  for (let j = 0; j < n; j++) {
    if (square[i][j] === 0) {
      zeroRow = i;
      zeroCol = j;
    }
  }
}

let magicSum = 0;
for (let i = 0; i < n; i++) {
  if (i !== zeroRow) {
    magicSum = square[i].reduce((sum, value) => sum + value, 0);
    break;
  }
}

const missingValue =
  magicSum - square[zeroRow].reduce((sum, value) => sum + value, 0);

console.log(missingValue);
console.log(zeroRow + 1);
console.log(zeroCol + 1);
